"""Notifications routes generated by ANG."""

from __future__ import annotations

from fastapi import APIRouter, Depends

from app import models
from app.services.notifications import NotificationsService, get_notifications_service

router = APIRouter(tags=["Notifications"])

@router.post("/notifications/invitation")
async def send_invitation_email(payload: models.SendInvitationEmailRequest, svc: NotificationsService = Depends(get_notifications_service)) -> models.SendInvitationEmailResponse:
    return await svc.send_invitation_email(payload)

@router.post("/notifications/password-reset")
async def send_password_reset_email(payload: models.SendPasswordResetEmailRequest, svc: NotificationsService = Depends(get_notifications_service)) -> models.SendPasswordResetEmailResponse:
    return await svc.send_password_reset_email(payload)

